#ifndef BOZ_HOST_SIGNATURES_H
#define BOZ_HOST_SIGNATURES_H

/* Argument kinds of the host functions the game calls, by import name (generated by
 * tools/gen_host_signatures.py into src/host_signatures.c). "<result>:<arguments>": i a word,
 * p a pointer, s a string result, l a 64-bit result, v no result. NULL for an unknown name. */
struct host_signature {
    const char *name;
    const char *signature;
};

const char *host_signature(const char *name);

/* The guest address of host function fn under its own name's signature. */
#define GUEST_FN(fn) arm_emu_guest_fn_sig((const void *)(uintptr_t)&(fn), host_signature(#fn))

#endif
